-- V90.fm: Intercompany X/Y Execution + Consolidated Elimination Control
-- Schema target: 239
CREATE TABLE IF NOT EXISTS intercompany_transaction (transaction_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, period_key TEXT NOT NULL, from_entity_id TEXT NOT NULL, to_entity_id TEXT NOT NULL, transaction_type TEXT NOT NULL DEFAULT 'STOCK_TRANSFER', reference_type TEXT, reference_id TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', posting_date DATE, currency TEXT NOT NULL DEFAULT 'INR', taxable_value NUMERIC NOT NULL DEFAULT 0, tax_value NUMERIC NOT NULL DEFAULT 0, total_value NUMERIC NOT NULL DEFAULT 0, narration TEXT, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, posted_by TEXT, posted_at TIMESTAMP, UNIQUE(organization_id,reference_type,reference_id));
CREATE TABLE IF NOT EXISTS intercompany_transaction_line (line_id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL, item_master_id TEXT NOT NULL, lot_id TEXT, quantity NUMERIC NOT NULL, uom TEXT NOT NULL, unit_value NUMERIC NOT NULL DEFAULT 0, line_value NUMERIC NOT NULL DEFAULT 0, from_location_id TEXT, from_warehouse_id TEXT, to_location_id TEXT, to_warehouse_id TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS intercompany_elimination (elimination_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, period_key TEXT NOT NULL, transaction_id TEXT NOT NULL, from_entity_id TEXT NOT NULL, to_entity_id TEXT NOT NULL, amount NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'OPEN', evidence_note TEXT, resolved_by TEXT, resolved_at TIMESTAMP, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(transaction_id));
CREATE TABLE IF NOT EXISTS intercompany_period_close (close_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, period_key TEXT NOT NULL, transaction_count INTEGER NOT NULL DEFAULT 0, posted_count INTEGER NOT NULL DEFAULT 0, open_elimination_count INTEGER NOT NULL DEFAULT 0, total_value NUMERIC NOT NULL DEFAULT 0, closed_by TEXT NOT NULL, closure_note TEXT, closed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,period_key));
CREATE INDEX IF NOT EXISTS ix_intercompany_tx_scope ON intercompany_transaction(organization_id,period_key,status,from_entity_id,to_entity_id);
CREATE INDEX IF NOT EXISTS ix_intercompany_elim_scope ON intercompany_elimination(organization_id,period_key,status);
